from common import *
S='G11_S26_01'; X=x
# A: x^2+1 on [0;2]
f=X**2+1; assert sp.diff(f,X)==2*X and continuous_domain(f,X,sp.Interval(0,2))==sp.Interval(0,2)
task(S,'A','Выполняются ли условия теоремы Лагранжа для функции $f(x)=x^{2}+1$ на отрезке $[0;\\,2]$?','Да: функция непрерывна на $[0;\\,2]$ и дифференцируема на $(0;\\,2)$',
 [('Нет: $f(0)\\neq f(2)$','Ученик перепутал условия теоремы Лагранжа с условиями теоремы Ролля: равенство значений на концах отрезка для теоремы Лагранжа не требуется.'),
  ('Нет: функция не дифференцируема в точке $x=0$','Ученик решил, что в нуле производная не существует; но $f\'(x)=2x$ существует при всех $x$.'),
  ('Нет: функция разрывна на отрезке','Ученик решил, что функция разрывна, не проверив непрерывность; но многочлен непрерывен на всей числовой прямой.')])
# B: 1/x on [-1;1]
assert continuous_domain(1/X,X,sp.Interval(-1,1))!=sp.Interval(-1,1)
task(S,'B','Выполняются ли условия теоремы Лагранжа для функции $f(x)=\\dfrac{1}{x}$ на отрезке $[-1;\\,1]$?','Нет: функция разрывна в точке $x=0$ отрезка',
 [('Да: функция дифференцируема на $(-1;\\,1)$','Ученик не заметил, что функция не определена в точке $x=0$, принадлежащей отрезку, и потому не непрерывна на $[-1;\\,1]$.'),
  ('Нет: $f(-1)\\neq f(1)$','Ученик перепутал условия теоремы Лагранжа с условиями теоремы Ролля: равенство значений на концах отрезка для теоремы Лагранжа не требуется.'),
  ('Да: функция непрерывна на концах отрезка','Ученик проверил непрерывность только в точках $-1$ и $1$ и не проверил внутренние точки отрезка.')])
# C: cbrt on [-1;8]
f=sp.real_root(X,3); d=sp.diff(X**sp.Rational(1,3),X); assert sp.simplify(d-X**sp.Rational(-2,3)/3)==0
assert sp.limit(sp.real_root(X,3)/X,X,0,'+')==sp.oo
task(S,'C','Выполняются ли условия теоремы Лагранжа для функции $f(x)=\\sqrt[3]{x}$ на отрезке $[-1;\\,8]$?','Нет: функция не дифференцируема в точке $x=0$ внутри отрезка',
 [('Да: функция непрерывна на отрезке','Ученик проверил только непрерывность и не проверил дифференцируемость во внутренних точках; в точке $x=0$ у графика вертикальная касательная.'),
  ('Да: $f\'(x)=\\dfrac{1}{3}x^{-2/3}$ существует при всех $x$','Ученик применил формулу производной степенной функции и не заметил, что $x^{-2/3}$ не определена при $x=0$.'),
  ('Нет: функция разрывна в точке $x=0$','Ученик перепутал отсутствие производной с разрывом; $\\sqrt[3]{x}$ непрерывна на всей числовой прямой.')])
save(S, expect=3)
